div.script:
                            (function() {
                                function loadStudents() {
                                    var subjectId = document.querySelector('[name="subject_id"]').value;
                                    var batchId = document.querySelector('[name="batch_id"]').value;
                                    var content = document.getElementById('studentListContent');
                                    var saveBtn = document.getElementById('saveAttendanceBtn');

                                    if (!subjectId || !batchId) {
                                        content.innerHTML = '
Select a subject and batch to load students.';
                                        saveBtn.disabled = true;
                                        return;
                                    }

                                    content.innerHTML = '
Loading students...';

                                    fetch('/my/faculty/attendance/students?subject_id=' + subjectId + '&batch_id=' + batchId)
                                        .then(function(r) { return r.json(); })
                                        .then(function(data) {
                                            if (!data.students || data.students.length === 0) {
                                                content.innerHTML = '
No students found for this batch.';
                                                saveBtn.disabled = true;
                                                return;
                                            }
                                            var table = document.createElement('table');
                                            table.className = 'table table-hover table-bordered align-middle';
                                            table.innerHTML = '
StudentReg NoStatus';
                                            var tbody = document.createElement('tbody');
                                            data.students.forEach(function(s) {
                                                var tr = document.createElement('tr');
                                                var tdName = document.createElement('td');
                                                tdName.textContent = s.name;
                                                var tdReg = document.createElement('td');
                                                tdReg.textContent = s.reg_no;
                                                var tdStatus = document.createElement('td');
                                                var sel = document.createElement('select');
                                                sel.name = 'attendance_' + s.id;
                                                sel.setAttribute('form', 'attendanceForm');
                                                sel.className = 'form-select form-select-sm'; sel.style.minWidth = '110px';
                                                ['present','absent','late'].forEach(function(val) {
                                                    var opt = document.createElement('option');
                                                    opt.value = val;
                                                    opt.textContent = val.charAt(0).toUpperCase() + val.slice(1);
                                                    sel.appendChild(opt);
                                                });
                                                tdStatus.appendChild(sel);
                                                tr.appendChild(tdName);
                                                tr.appendChild(tdReg);
                                                tr.appendChild(tdStatus);
                                                tbody.appendChild(tr);
                                            });
                                            table.appendChild(tbody);
                                            content.innerHTML = '';
                                            content.appendChild(table);
                                            var html = '';
                                            saveBtn.disabled = false;
                                        })
                                        .catch(function() {
                                            content.innerHTML = '
Error loading students.';
                                            saveBtn.disabled = true;
                                        });
                                }

                                document.querySelector('[name="subject_id"]').addEventListener('change', loadStudents);
                                document.querySelector('[name="batch_id"]').addEventListener('change', loadStudents);

                                // Auto-load if values already selected
                                document.getElementById('markAttendanceModal').addEventListener('shown.bs.modal', loadStudents);
                            })();
